INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15001, 'Psalms 119:91', 'Psalms', 119, 91, '&nbsp;ستا شريعت تر نن ورځې پورې قائم دے نو ټول څيزونه ستا خِدمتګاران دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15002, 'Psalms 119:92', 'Psalms', 119, 92, '&nbsp;کۀ چرې ستا شريعت زما خوشحالى نۀ وے نو زۀ به په خپل مصيبت کښې تباه شوے ومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15003, 'Psalms 119:93', 'Psalms', 119, 93, '&nbsp;زۀ به هيڅکله هم ستا تعليمات نۀ هېرومه ځکه چې په دوئ باندې تا زما ژوند تازه ساتلے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15004, 'Psalms 119:94', 'Psalms', 119, 94, '&nbsp;ما بچ کړه ځکه چې زۀ ستا يمه ما ستا د تعليماتو لټون کړے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15005, 'Psalms 119:95', 'Psalms', 119, 95, '&nbsp;بدکاران زما د تباه کولو په انتظار کښې دى خو زۀ به ستا په قانون غور کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15006, 'Psalms 119:96', 'Psalms', 119, 96, '&nbsp;تر دې چې زۀ د هر يو کامِل کار څۀ حد وينمه خو ستا د حُکمونو څۀ حد نۀ وينمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15007, 'Psalms 119:97', 'Psalms', 119, 97, '&nbsp;خو ګوره زۀ ستا د قانون سره څومره مينه کومه او زۀ ټوله ورځ په دې سوچ کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15008, 'Psalms 119:98', 'Psalms', 119, 98, '&nbsp;ستا حُکمونه ما د خپلو دشمنانو نه ډېر هوښياروى ځکه چې هغه ما سره د تل دپاره دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15009, 'Psalms 119:99', 'Psalms', 119, 99, '&nbsp;زۀ د خپلو ټولو اُستاذانو نه ډېر هوښيار يمه نو ځکه زۀ ستا په شريعت غور کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15010, 'Psalms 119:100', 'Psalms', 119, 100, '&nbsp;زۀ د مشرانو نه ډېره زياته هوښيارتيا لرمه ځکه چې زۀ ستا په شريعت عمل کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15011, 'Psalms 119:101', 'Psalms', 119, 101, '&nbsp;ما د هرې بدې لارې نه خپل قدمونه ساتلى دى نو چې زۀ ستا په کلام عمل وکړے شمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15012, 'Psalms 119:102', 'Psalms', 119, 102, '&nbsp;زۀ ستا د شريعت نه جدا شوے نۀ يمه ځکه چې تا په خپله ما ته تعليم راکړے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15013, 'Psalms 119:103', 'Psalms', 119, 103, '&nbsp;ستا کلام زما دپاره څومره خوږ دے زما د خولې دپاره د شاتو نه ډېر خوږ دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15014, 'Psalms 119:104', 'Psalms', 119, 104, '&nbsp;ما عقل ستا د تعليماتو نه زده کړو نو په دې وجه د غلطو لارو نه نفرت کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15015, 'Psalms 119:105', 'Psalms', 119, 105, '&nbsp;ستا کلام زما د پښو دپاره ډيوه ده او زما د لارې دپاره رڼا ده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15016, 'Psalms 119:106', 'Psalms', 119, 106, '&nbsp;ما قسم خوړلے او په هغې ولاړ يم چې زۀ به ستا په صادق شريعت باندې عمل کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15017, 'Psalms 119:107', 'Psalms', 119, 107, '&nbsp;اے مالِکه خُدايه ما ډېر تکليفونه تېر کړل د خپل کلام په مطابق دې زما ژوند تازه کړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15018, 'Psalms 119:108', 'Psalms', 119, 108, '&nbsp;اے مالِکه خُدايه زما د خولې نه د اخلاص نه ډک ثناء صِفت قبول کړه او د خپل شريعت تعليم دې ما ته راکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15019, 'Psalms 119:109', 'Psalms', 119, 109, '&nbsp;کۀ څۀ هم چې هر وخت خپل ژوند په خطره کښې اچومه خو زۀ به ستا شريعت نۀ هېرومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15020, 'Psalms 119:110', 'Psalms', 119, 110, '&nbsp;بدکارانو ما ته دام خور کړے دے خو بيا هم زۀ ستا د تعليماتو نه بې‌لارې نۀ شومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15021, 'Psalms 119:111', 'Psalms', 119, 111, '&nbsp;ستا حُکمونه مې د تل دپاره ميراث دے دا زما د زړۀ خوشحالى ده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15022, 'Psalms 119:112', 'Psalms', 119, 112, '&nbsp;زما زړۀ ستا د حُکمونو په ساتلو بوخت دے او دا قانون به تر ابده پورې منمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15023, 'Psalms 119:113', 'Psalms', 119, 113, '&nbsp;زۀ دوه مخيزه سړى نه کرکه کومه خو زۀ ستا قانون سره مينه کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15024, 'Psalms 119:114', 'Psalms', 119, 114, '&nbsp;تۀ زما پناه او زما ډال يې ما خپل اُميد ستا د کلام پورې تړلے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15025, 'Psalms 119:115', 'Psalms', 119, 115, '&nbsp;اے بدکارو خلقو ما نه لرې شئ چې زۀ د خپل خُدائ پاک په حُکمونو عمل وکړمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15026, 'Psalms 119:116', 'Psalms', 119, 116, '&nbsp;د خپلې وعدې په مطابق دې ما سمبال کړه چې زۀ ژوندے پاتې شمه او د خپل اُميد نه دې شرمنده نۀ شمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15027, 'Psalms 119:117', 'Psalms', 119, 117, '&nbsp;ما ته سهاره راکړه نو زۀ به بچ شمه نو بيا به زۀ د تل دپاره ستا په شريعت غور کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15028, 'Psalms 119:118', 'Psalms', 119, 118, '&nbsp;تۀ هغوئ ټول رد کوې څوک چې ستا د شريعت نه اوړى او د هغوئ دوکه بلکل عبث ده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15029, 'Psalms 119:119', 'Psalms', 119, 119, '&nbsp;تۀ د دُنيا ټول بدعمله لکه د خزلې په شان غورزوې نو په دې وجه زۀ ستا قانون سره مينه کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15030, 'Psalms 119:120', 'Psalms', 119, 120, '&nbsp;ستا د يرې نه زما بدن رپى او زۀ ستا د عدالت نه يرېږمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15031, 'Psalms 119:121', 'Psalms', 119, 121, '&nbsp;ما هغه څۀ وکړل څۀ چې صداقت او اِنصاف وى ما خپلو دشمنانو ته مۀ پرېږده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15032, 'Psalms 119:122', 'Psalms', 119, 122, '&nbsp;خپل خِدمتګار ته د ښۀ ژوند ضمانت ورکړه کبرژن مۀ پرېږده چې په ما ظلم وکړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15033, 'Psalms 119:123', 'Psalms', 119, 123, '&nbsp;ستا خلاصون پسې سترګې مې ستړې شوې او ستا د رښتينې وعدې انتظار کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15034, 'Psalms 119:124', 'Psalms', 119, 124, '&nbsp;د خپل خِدمتګار سره دې د خپلې ابدى مينې په مطابق سلوک وکړه او د خپلو اصُولو تعليم دې ما ته راکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15035, 'Psalms 119:125', 'Psalms', 119, 125, '&nbsp;زۀ ستا خِدمتګار يم ما له پوهه راکړه چې زۀ ستا په قانون باندې پوهه شمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15036, 'Psalms 119:126', 'Psalms', 119, 126, '&nbsp;اے مالِکه خُدايه اوس ستا د قدم اوچتولو دا وخت دے ځکه چې ستا قانون مات شوے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15037, 'Psalms 119:127', 'Psalms', 119, 127, '&nbsp;ځکه زۀ ستا د حُکمونو سره مينه کومه د سرو زرو نه زياته او د خالص سرو زرو نه زياته', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15038, 'Psalms 119:128', 'Psalms', 119, 128, '&nbsp;او ځکه زۀ ستا ټول تعليمات صحيح ګڼمه او زۀ د هر يوې خطا لارې نه نفرت کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15039, 'Psalms 119:129', 'Psalms', 119, 129, '&nbsp;ستا شريعت ښکلے دے نو ځکه زۀ په دې باندې عمل کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15040, 'Psalms 119:130', 'Psalms', 119, 130, '&nbsp;ستا د کلام تعليم نُور ورکوى او جاهلانو خلقو ته پوهه ورکوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15041, 'Psalms 119:131', 'Psalms', 119, 131, '&nbsp;ستا د حُکمونو دومره تږے يمه چې د حُکمونو ارمانى دې يمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15042, 'Psalms 119:132', 'Psalms', 119, 132, '&nbsp;ما ته راشه او په ما رحم وکړه څنګه چې تۀ تل د هغوئ سره مينه کوې، څوک چې ستا نوم سره مينه کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15043, 'Psalms 119:133', 'Psalms', 119, 133, '&nbsp;زما قدمونه ستا د کلام په لاره روان کړه او هيڅ قسمه ګناه دې په ما حکومت نۀ کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15044, 'Psalms 119:134', 'Psalms', 119, 134, '&nbsp;ما ته د انسان د ظلم زور نه خلاصون راکړه نو چې زۀ ستا په تعليماتو باندې عمل وکړمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15045, 'Psalms 119:135', 'Psalms', 119, 135, '&nbsp;خپل د مخ رڼا دې په خپل خِدمتګار وځلوه او د خپل شريعت تعليم دې ما ته راکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15046, 'Psalms 119:136', 'Psalms', 119, 136, '&nbsp;د اوښکو سېلابونه مې د سترګو نه بهيږى ځکه چې ستا په شريعت باندې عمل نۀ کيږى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15047, 'Psalms 119:137', 'Psalms', 119, 137, '&nbsp;تۀ صادقه يې اے مالِکه خُدايه او ستا فېصلې د اِنصاف دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15048, 'Psalms 119:138', 'Psalms', 119, 138, '&nbsp;کوم شريعت چې تا مقرر کړے دے هغه د صداقت نه ډک دے او هغه بلکل باورى دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15049, 'Psalms 119:139', 'Psalms', 119, 139, '&nbsp;زما غېرت ما سوزوى ځکه چې زما دشمنانو ستا کلام هېر کړے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15050, 'Psalms 119:140', 'Psalms', 119, 140, '&nbsp;ستا کلام ډېر پاک دے نو ځکه ستا خِدمتګار د هغې سره مينه کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15051, 'Psalms 119:141', 'Psalms', 119, 141, '&nbsp;کۀ څۀ هم چې زۀ ورکوټے او حقير يمه خو زۀ ستا تعليمات نۀ هېرومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15052, 'Psalms 119:142', 'Psalms', 119, 142, '&nbsp;ستا صداقت ابدى دے او ستا قانون رښتونے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15053, 'Psalms 119:143', 'Psalms', 119, 143, '&nbsp;غم او تکليف ما باندې راغلے دے خو ستا په حُکمونو کښې زما خوشحالى ده', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15054, 'Psalms 119:144', 'Psalms', 119, 144, '&nbsp;ستا اصُول تر ابده صحيح دى ما له پوهه راکړه چې زۀ ژوندے پاتې شمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15055, 'Psalms 119:145', 'Psalms', 119, 145, '&nbsp;د خپل ټول زړۀ سره تا ته سوال زارى کومه جواب راکړه مالِک خُدايه زۀ به ستا په شريعت باندې عمل کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15056, 'Psalms 119:146', 'Psalms', 119, 146, '&nbsp;زۀ تا ته سوال کومه ما بچ کړه چې زۀ به ستا په شريعت باندې عمل کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15057, 'Psalms 119:147', 'Psalms', 119, 147, '&nbsp;سحر سبا راپاڅمه او د مدد دپاره تا ته سوال زارى کومه او زۀ ستا په کلام خپل اُميد تړمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15058, 'Psalms 119:148', 'Psalms', 119, 148, '&nbsp;ټوله شپه زما سترګې کولاو وى چې زۀ ستا په وعدو باندې غور وکړمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15059, 'Psalms 119:149', 'Psalms', 119, 149, '&nbsp;د خپلې مينې په مطابق دې زما آواز واوره د خپل رحم په مطابق دې زما ژوند بچ کړه اے مالِکه خُدايه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15060, 'Psalms 119:150', 'Psalms', 119, 150, '&nbsp;څوک چې بدې منصوبې جوړوى ما ته رانزدې دى خو دوئ ستا د شريعت نه لرى دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15061, 'Psalms 119:151', 'Psalms', 119, 151, '&nbsp;خو اوس تۀ رانزدې يې اے مالِکه خُدايه او ستا حُکمونه ټول صحيح دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15062, 'Psalms 119:152', 'Psalms', 119, 152, '&nbsp;ډېر د پخوا نه ما ستا د قانون نه زده کړى دى چې تۀ هغه همېشه دپاره قائم ساتې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15063, 'Psalms 119:153', 'Psalms', 119, 153, '&nbsp;زما مصيبت ته وګوره او ما بچ کړه ځکه چې ما ستا قانون هېر کړے نۀ دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15064, 'Psalms 119:154', 'Psalms', 119, 154, '&nbsp;په عدالت کښې زما دفاع وکړه او آزاد مې کړه او د خپلې وعدې په مطابق دې زما ژوند وساته', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15065, 'Psalms 119:155', 'Psalms', 119, 155, '&nbsp;خلاصون د بدعملو نه لرې دے ځکه چې هغوئ ستا د قانون لټون نۀ کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15066, 'Psalms 119:156', 'Psalms', 119, 156, '&nbsp;ستا رحم ډېر لوئ دے اے مالِکه خُدايه او د خپل شريعت په مطابق دې زما ژوند بچ کړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15067, 'Psalms 119:157', 'Psalms', 119, 157, '&nbsp;زما دشمنان ډېر دى څوک چې ما ازاروى خو زۀ ستا د شريعت نه اوړېدلے نۀ يم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15068, 'Psalms 119:158', 'Psalms', 119, 158, '&nbsp;زۀ بې‌ايمانانو ته سپک ګورمه ځکه چې دوئ ستا په کلام عمل نۀ کوى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15069, 'Psalms 119:159', 'Psalms', 119, 159, '&nbsp;او ګوره زۀ ستا د حُکمونو سره څومره مينه کومه د خپلې ابدى مينې په مطابق دې زما ژوند بچ کړه اے مالِکه خُدايه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15070, 'Psalms 119:160', 'Psalms', 119, 160, '&nbsp;ستا ټول کلام رښتونے دے او ستا ټول صادق کلام ابدى دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15071, 'Psalms 119:161', 'Psalms', 119, 161, '&nbsp;بادشاهان بې‌وجې ما ازاروى خو زما زړۀ ستا په کلام د يرې نه درزيږى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15072, 'Psalms 119:162', 'Psalms', 119, 162, '&nbsp;زۀ ستا په وعدو کښې خوشحالى کومه لکه څوک چې پېدا کړى لويه خزانه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15073, 'Psalms 119:163', 'Psalms', 119, 163, '&nbsp;زۀ دروغ بد ګڼم او ترې نه نفرت کومه خو زۀ ستا قانون سره مينه کومه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15074, 'Psalms 119:164', 'Psalms', 119, 164, '&nbsp;په ورځ کښې زۀ اووۀ ځله ستا ثناء وايمه ځکه چې ستا ټول شريعت د اِنصاف دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15075, 'Psalms 119:165', 'Psalms', 119, 165, '&nbsp;هغوئ په لوئ امن کښې دى څوک چې ستا قانون سره مينه کوى او هيڅ څيز به هغوئ له تيندک ورنۀ کړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
