(15077, 'Psalms 119:167', 'Psalms', 119, 167, '&nbsp;زۀ ستا په تعليماتو باندې عمل کومه ځکه چې زۀ ورسره ډېره مينه لرمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15078, 'Psalms 119:168', 'Psalms', 119, 168, '&nbsp;زۀ ستا تعليماتو شريعت باندې عمل کومه ځکه چې تۀ خبر يې زما د ټولو کارونو نه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15079, 'Psalms 119:169', 'Psalms', 119, 169, '&nbsp;زما سوال زارى دې تا ته درورسيږى اے مالِکه خُدايه د خپل کلام په مطابق دې ما له پوهه راکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15080, 'Psalms 119:170', 'Psalms', 119, 170, '&nbsp;زما خواستونه دې تا ته درورسيږى د خپل کلام په مطابق دې ما له ژوند راکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15081, 'Psalms 119:171', 'Psalms', 119, 171, '&nbsp;زما په ژبه دې ستا ثناء صِفت وى ځکه چې تا ما ته خپل قانون ښودلے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15082, 'Psalms 119:172', 'Psalms', 119, 172, '&nbsp;زما ژبه دې ستا د کلام سندرې ووائى ځکه چې ستا ټول حُکمونه صادق دى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15083, 'Psalms 119:173', 'Psalms', 119, 173, '&nbsp;ستا لاس دې هر وخت زما د مدد دپاره تيار وى ځکه چې ما ستا شريعت غوره کړے دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15084, 'Psalms 119:174', 'Psalms', 119, 174, '&nbsp;ستا د خلاصون زۀ ارمانى يمه اے مالِکه خُدايه او زۀ ستا په شريعت کښې خوشحاله يمه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15085, 'Psalms 119:175', 'Psalms', 119, 175, '&nbsp;ما ته ژوند راکړه ترڅو ستا ثناء صِفت وکړمه او ستا قانون دې ما وساتى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15086, 'Psalms 119:176', 'Psalms', 119, 176, '&nbsp;زۀ د ورکې شوې ګډې په شان بې‌لارې شوے يمه خپل خِدمت کوونکے دې ولټوه ځکه چې ما هېر کړى نۀ دى ستا حُکمونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15087, 'Psalms 120:1', 'Psalms', 120, 1, '&nbsp;په سخته کښې مالِک خُدائ ته سوال زارى کوم، او زما سوال هغه قبلوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15088, 'Psalms 120:2', 'Psalms', 120, 2, '&nbsp;ما د دروغژنو شونډو نه بچ کړه اے مالِکه خُدايه او د دوکه بازو ژبو نه مې وساته', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15089, 'Psalms 120:3', 'Psalms', 120, 3, '&nbsp;اے دوکه مارو ژبو هغه به تاسو سره څۀ وکړى؟ او د دې سزا سره به نور تاسو سره څۀ وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15090, 'Psalms 120:4', 'Psalms', 120, 4, '&nbsp;هغه به تاسو ته د جنګيالو د تېرو غشو سره سزا درکړى، او په سرو سکروټو به سزا درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15091, 'Psalms 120:5', 'Psalms', 120, 5, '&nbsp;افسوس دې وى په ما چې زۀ په مسک کښې لکه مسافر اوسېږم، زۀ د قيدار د خېمو په مينځ کښې اوسېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15092, 'Psalms 120:6', 'Psalms', 120, 6, '&nbsp;زۀ ډېر زيات اوسېدلے يم د هغو خلقو په مينځ کښې څوک چې امن نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15093, 'Psalms 120:7', 'Psalms', 120, 7, '&nbsp;زۀ صُلح خوښوونکے او امن پسند يم، خو چې کله زۀ د صُلحې خبرې کوم هغوئ جنګ غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15094, 'Psalms 121:1', 'Psalms', 121, 1, '&nbsp;ما خپلې سترګې غرونو ته نيولې دى. چې زما مدد به د کوم ځايه راځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15095, 'Psalms 121:2', 'Psalms', 121, 2, '&nbsp;زما مدد د مالِک خُدائ نه راځى، چې د زمکې او آسمان جوړونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15096, 'Psalms 121:3', 'Psalms', 121, 3, '&nbsp;ستا پښې به هغه ښوئېدو ته نۀ پرېږدى، هغه څوک چې ستا حِفاظت کوى هغۀ له خوب نۀ ورځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15097, 'Psalms 121:4', 'Psalms', 121, 4, '&nbsp;په حقيقت کښې هغه څوک چې د بنى اِسرائيلو حفاظت کوى، هغۀ ته نۀ خوب جوټه ورکوى او نۀ اودۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15098, 'Psalms 121:5', 'Psalms', 121, 5, '&nbsp;مالِک خُدائ ستاسو حفاظت کوى، مالِک خُدائ لکه د سورې په شان تا سره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15099, 'Psalms 121:6', 'Psalms', 121, 6, '&nbsp;په ورځ کښې به نمر تکليف نۀ درکوى، او نۀ به سپوږمۍ په شپه کښې نقصان درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15100, 'Psalms 121:7', 'Psalms', 121, 7, '&nbsp;مالِک خُدائ به ستاسو د هر مصيبت نه حفاظت کوى، هغه به ستا په ژوند باندې نظر ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');